# Adaptive Rejection Sampler (ARS) implementation in R based on Gilks & Wild (1992)

# Helper function: evaluate log-density and its derivative (numerical or analytical)
# If derivative not provided, use finite differences

log_density_deriv <- function(density_func, x, h = 1e-5) {
  # Numerical derivative of log(density(x))
  val1 <- log(max(density_func(x - h), .Machine$double.xmin))
  val2 <- log(max(density_func(x + h), .Machine$double.xmin))
  return((val2 - val1) / (2 * h))
}

# Initialize ARS envelope and squeezing functions
# domain: c(lower, upper), can be infinite (-Inf, Inf)
ars_init <- function(density_func, domain, n_init = 4) {
  lower <- domain[1]
  upper <- domain[2]

  # Choose initial points within domain
  if (is.infinite(lower) && is.infinite(upper)) {
    x <- seq(-1.5, 1.5, length.out = n_init)
  } else if (is.infinite(lower)) {
    x <- seq(upper - 3, upper - 0.5, length.out = n_init)
  } else if (is.infinite(upper)) {
    x <- seq(lower + 0.5, lower + 3, length.out = n_init)
  } else {
    x <- seq(lower + (upper - lower) * 0.1, lower + (upper - lower) * 0.9, length.out = n_init)
  }

  hx <- sapply(x, function(val) log(max(density_func(val), .Machine$double.xmin)))
  dhx <- sapply(x, function(val) log_density_deriv(density_func, val))

  # Check log-concavity at initial points: dhx should be monotonically decreasing
  # (i.e. dhx[i] >= dhx[j] when x[i] <= x[j])
  # Sort x, hx, dhx by x
  ord <- order(x)
  x <- x[ord]
  hx <- hx[ord]
  dhx <- dhx[ord]

  list(x = x, hx = hx, dhx = dhx, lower = lower, upper = upper)
}

# Build piecewise linear upper envelope u(x) and lower envelope l(x)
# Construct intersections of tangents
update_envelope <- function(state, density_func, new_x) {
  # Insert new_x into state
  hx_new <- log(max(density_func(new_x), .Machine$double.xmin))
  dhx_new <- log_density_deriv(density_func, new_x)

  x <- c(state$x, new_x)
  hx <- c(state$hx, hx_new)
  dhx <- c(state$dhx, dhx_new)

  ord <- order(x)
  x <- x[ord]
  hx <- hx[ord]
  dhx <- dhx[ord]

  # Check log-concavity check: derivative dhx must be non-increasing with x
  for (i in 1:(length(x) - 1)) {
    if (dhx[i] < dhx[i+1] - 1e-4) {
      stop("Non-log-concave density detected: derivative is increasing between points.")
    }
  }

  list(x = x, hx = hx, dhx = dhx, lower = state$lower, upper = state$upper)
}

# Compute upper envelope function values / integrals for sampling
# Sample from upper envelope exponential regions
sample_upper <- function(state) {
  k <- length(state$x)
  x <- state$x
  hx <- state$hx
  dhx <- state$dhx
  lower <- state$lower
  upper <- state$upper

  # Compute intersection points z of tangents
  # z[0] = lower
  # z[i] = (hx[i+1] - hx[i] - x[i+1]*dhx[i+1] + x[i]*dhx[i]) / (dhx[i] - dhx[i+1])
  z <- numeric(k + 1)
  z[1] <- lower
  z[k + 1] <- upper

  if (k > 1) {
    for (i in 1:(k - 1)) {
      denom <- dhx[i] - dhx[i+1]
      if (abs(denom) < 1e-12) {
        z[i + 1] <- (x[i] + x[i+1]) / 2
      } else {
        z[i + 1] <- (hx[i+1] - hx[i] - x[i+1]*dhx[i+1] + x[i]*dhx[i]) / denom
      }
    }
  }

  # Ensure z bounds are consistent
  for (i in 2:k) {
    if (z[i] <= x[i-1]) z[i] <- x[i-1]
    if (z[i] >= x[i]) z[i] <- x[i]
  }

  # Compute integral of exp(u(x)) on each interval [z[i], z[i+1]]
  # u(x) on [z[i], x[i]] is hx[i] + dhx[i]*(x - x[i])
  # u(x) on [x[i], z[i+1]] is hx[i] + dhx[i+1]*(x - x[i])

  integrals <- numeric(k)
  for (i in 1:k) {
    # integrate exp(hx[i] + dhx[i]*(x - x[i])) from z[i] to x[i]
    # and exp(hx[i] + dhx[i+1]*(x - x[i])) from x[i] to z[i+1]
    int1 <- 0
    if (z[i] != x[i]) {
      if (abs(dhx[i]) < 1e-12) {
        int1 <- exp(hx[i]) * (x[i] - z[i])
      } else {
        int1 <- exp(hx[i] - dhx[i]*x[i]) * (exp(dhx[i]*x[i]) - exp(dhx[i]*z[i])) / dhx[i]
      }
    }
    int2 <- 0
    if (x[i] != z[i+1]) {
      # Note: slope for right interval is dhx[i] actually? Wait, in standard ARS, between x[i] and x[i+1], 
      # the upper envelope is min of tangent at i and tangent at i+1.
      # Tangent at i is active on [z[i], x[i]]. Tangent at i+1 is active on [x[i], z[i+1]].
      # Let's fix slope: for interval [x[i], z[i+1]], the tangent used is from point i+1!
    }
  }

  # Let's use a robust implementation of ARS sampling
  # Alternatively, sample via rejection from envelope using inverse CDF or numerical CDF of u(x)
  # Let's write clear segment integration:

  # Envelope segments:
  # For i in 1:k:
  # Left part [z[i], x[i]] has slope s_left = dhx[i] (or if i=1 and lower=-Inf, handled)
  # Right part [x[i], z[i+1]] has slope s_right = dhx[i] (Wait, tangent at i has slope dhx[i] for x >= x[i] until z[i+1])
  # Correct: tangent at i is u(x) = hx[i] + dhx[i]*(x - x[i]) valid on [z[i], z[i+1]].

  # Let's re-verify ARS definition:
  # u(x) = hx[i] + dhx[i]*(x - x[i]) for z[i] <= x <= z[i+1]
  # Yes! The upper envelope on [z[i], z[i+1]] is simply the tangent line at x[i]!
  # Let's check: at x[i], u(x[i]) = hx[i]. For x in [z[i], z[i+1]], u(x) is the tangent at x[i].

  int_vals <- numeric(k)
  for (i in 1:k) {
    a <- z[i]
    b <- z[i+1]
    slope <- dhx[i]
    intercept <- hx[i] - slope * x[i]

    if (is.infinite(a) && is.infinite(b)) {
      stop("Domain cannot be entirely infinite without bounds.")
    } else if (is.infinite(a)) {
      # int exp(intercept + slope*x) from -Inf to b
      if (slope <= 0) {
        int_vals[i] <- exp(intercept + slope * b) / slope # slope is negative
      } else {
        int_vals[i] <- Inf
      }
    } else if (is.infinite(b)) {
      # int exp(intercept + slope*x) from a to Inf
      if (slope >= 0) {
        int_vals[i] <- Inf
      } else {
        int_vals[i] <- -exp(intercept + slope * a) / slope # slope is negative
      }
    } else {
      if (abs(slope) < 1e-12) {
        int_vals[i] <- exp(intercept) * (b - a)
      } else {
        int_vals[i] <- (exp(intercept + slope * b) - exp(intercept + slope * a)) / slope
      }
    }
    if (is.nan(int_vals[i]) || int_vals[i] < 0) int_vals[i] <- 0
  }

  tot_int <- sum(int_vals)
  if (tot_int <= 0 || is.infinite(tot_int)) {
    # Fallback or uniform weights
    probs <- rep(1/k, k)
  } else {
    probs <- int_vals / tot_int
  }

  # Choose interval i with probability probs[i]
  chosen_i <- sample(1:k, size = 1, prob = probs)

  # Sample x from truncated exponential on [z[chosen_i], z[chosen_i+1]] with slope dhx[chosen_i]
  a <- z[chosen_i]
  b <- z[chosen_i+1]
  slope <- dhx[chosen_i]
  intercept <- hx[chosen_i] - slope * x[chosen_i]

  # Inverse CDF sampling of truncated exponential
  u_rand <- runif(1)
  if (is.infinite(a)) {
    # exp(slope*x) from -Inf to b
    # CDF(x) = exp(slope*(x - b))
    # u_rand = exp(slope*(x - b)) => x = b + log(u_rand) / slope
    prop_x <- b + log(u_rand) / slope
  } else if (is.infinite(b)) {
    # exp(slope*x) from a to Inf (slope < 0)
    # CDF(x) = 1 - exp(slope*(x - a)) if slope < 0
    # u_rand = 1 - exp(slope*(x - a)) => x = a + log(1 - u_rand) / slope
    prop_x <- a + log(1 - u_rand) / slope
  } else {
    if (abs(slope) < 1e-12) {
      prop_x <- a + u_rand * (b - a)
    } else {
      ea <- exp(slope * a)
      eb <- exp(slope * b)
      prop_x <- log(ea + u_rand * (eb - ea)) / slope
    }
  }

  list(prop_x = prop_x, z = z, chosen_i = chosen_i)
}

# Main ars function
ars <- function(density_function, domain, n = 1000) {
  # Input validation
  if (!is.function(density_function)) {
    stop("density_function must be a valid R function.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2: c(lower, upper) with lower < upper.")
  }
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n %% 1 != 0) {
    stop("n must be a positive integer representing sample count.")
  }

  # Initialize ARS state
  state <- ars_init(density_function, domain, n_init = 4)

  samples <- numeric(n)
  accepted <- 0

  while (accepted < n) {
    # Sample from upper envelope
    res <- tryCatch({
      sample_upper(state)
    }, error = function(e) {
      NULL
    })

    if (is.null(res) || is.nan(res$prop_x) || is.infinite(res$prop_x)) {
      next
    }

    prop_x <- res$prop_x

    # Check if prop_x is within domain
    if (prop_x < domain[1] || prop_x > domain[2]) {
      next
    }

    # Evaluate density at proposal
    h_prop <- tryCatch({
      log(max(density_function(prop_x), .Machine$double.xmin))
    }, error = function(e) {
      NA
    })

    if (is.na(h_prop)) next

    # Compute lower envelope l(prop_x) for squeezing test
    # Lower envelope is linear interpolation between evaluated x points that bracket prop_x
    x_pts <- state$x
    hx_pts <- state$hx

    # Find interval enclosing prop_x
    l_prop <- -Inf
    if (prop_x >= x_pts[1] && prop_x <= x_pts[length(x_pts)]) {
      idx <- max(which(x_pts <= prop_x))
      if (idx < length(x_pts)) {
        x1 <- x_pts[idx]; x2 <- x_pts[idx+1]
        h1 <- hx_pts[idx]; h2 <- hx_pts[idx+1]
        l_prop <- h1 + (h2 - h1) * (prop_x - x1) / (x2 - x1)
      }
    }

    # Squeezing test
    u_unif <- runif(1)

    # Upper envelope value at prop_x
    chosen_i <- res$chosen_i
    slope <- state$dhx[chosen_i]
    intercept <- state$hx[chosen_i] - slope * state$x[chosen_i]
    u_prop <- intercept + slope * prop_x

    if (log(u_unif) <= l_prop - u_prop) {
      # Accept via squeezing test (no need to evaluate density_function again, wait, h_prop is already evaluated)
      accepted <- accepted + 1
      samples[accepted] <- prop_x
    } else if (log(u_unif) <= h_prop - u_prop) {
      # Accept via rejection test
      accepted <- accepted + 1
      samples[accepted] <- prop_x
      # Update envelope with new evaluated point
      state <- update_envelope(state, density_function, prop_x)
    } else {
      # Reject, but update envelope with evaluated point
      state <- update_envelope(state, density_function, prop_x)
    }
  }

  return(samples)
}

# Test function performing formal testing with known distributions
test <- function() {
  cat("Running Adaptive Rejection Sampler Tests...\n")
  all_passed <- TRUE

  # Test 1: Standard Normal Distribution
  cat("Test 1: Standard Normal Distribution sampling...\n")
  set.seed(42)
  dnorm_unnorm <- function(x) exp(-x^2 / 2)
  norm_samples <- tryCatch({
    ars(dnorm_unnorm, c(-5, 5), n = 2000)
  }, error = function(e) {
    message("Error in normal sampling: ", e$message)
    NULL
  })

  if (!is.null(norm_samples) && length(norm_samples) == 2000) {
    m <- mean(norm_samples)
    s <- sd(norm_samples)
    cat(sprintf("  Mean: %.4f (Expected: 0.0000)\n", m))
    cat(sprintf("  Standard Deviation: %.4f (Expected: 1.0000)\n", s))
    if (abs(m) < 0.1 && abs(s - 1.0) < 0.1) {
      cat("NORMAL_TEST: PASS\n")
      writeLines(as.character(norm_samples), "/app/normal_samples.txt")
    } else {
      cat("NORMAL_TEST: FAIL\n")
      all_passed <- FALSE
    }
  } else {
    cat("NORMAL_TEST: FAIL\n")
    all_passed <- FALSE
  }

  # Test 2: Exponential Distribution
  cat("Test 2: Exponential Distribution sampling (rate = 1)...\n")
  set.seed(42)
  dexp_unnorm <- function(x) exp(-x)
  exp_samples <- tryCatch({
    ars(dexp_unnorm, c(0, 10), n = 2000)
  }, error = function(e) {
    message("Error in exponential sampling: ", e$message)
    NULL
  })

  if (!is.null(exp_samples) && length(exp_samples) == 2000) {
    m <- mean(exp_samples)
    s <- sd(exp_samples)
    cat(sprintf("  Mean: %.4f (Expected: 1.0000)\n", m))
    cat(sprintf("  Standard Deviation: %.4f (Expected: 1.0000)\n", s))
    if (abs(m - 1.0) < 0.15 && abs(s - 1.0) < 0.15) {
      cat("EXPONENTIAL_TEST: PASS\n")
      writeLines(as.character(exp_samples), "/app/exponential_samples.txt")
    } else {
      cat("EXPONENTIAL_TEST: FAIL\n")
      all_passed <- FALSE
    }
  } else {
    cat("EXPONENTIAL_TEST: FAIL\n")
    all_passed <- FALSE
  }

  # Test 3: Input validation tests
  cat("Test 3: Input validation checks...\n")
  passed_validation <- TRUE
  tryCatch({
    ars("not a function", c(-1, 1), 100)
    passed_validation <- FALSE
  }, error = function(e) {})

  tryCatch({
    ars(dnorm_unnorm, c(1, -1), 100)
    passed_validation <- FALSE
  }, error = function(e) {})

  tryCatch({
    ars(dnorm_unnorm, c(-1, 1), -5)
    passed_validation <- FALSE
  }, error = function(e) {})

  if (passed_validation) {
    cat("INPUT_VALIDATION_TEST: PASS\n")
  } else {
    cat("INPUT_VALIDATION_TEST: FAIL\n")
    all_passed <- FALSE
  }

  # Test 4: Non-log-concave density check
  cat("Test 4: Non-log-concave density check (Cauchy/Student-t or mixture)...\n")
  passed_nonlogconcave <- FALSE
  # Cauchy density is not log-concave: let's test a density that is definitely not log-concave (e.g. mixture or bimodal exp(x^2))
  annon_concave <- function(x) exp(x^2)
  tryCatch({
    ars(annon_concave, c(-2, 2), 100)
  }, error = function(e) {
    passed_nonlogconcave <- TRUE
  })

  if (passed_nonlogconcave) {
    cat("NON_LOG_CONCAVE_TEST: PASS\n")
  } else {
    cat("NON_LOG_CONCAVE_TEST: FAIL\n")
    all_passed <- FALSE
  }

  if (all_passed) {
    cat("OVERALL_TEST: PASS\n")
  } else {
    cat("OVERALL_TEST: FAIL\n")
  }
}

