# Adaptive Rejection Sampler (ARS) implementation in R based on Gilks & Wild (1992)

log_density_deriv <- function(density_func, x, h = 1e-5) {
  val1 <- log(max(density_func(x - h), .Machine$double.xmin))
  val2 <- log(max(density_func(x + h), .Machine$double.xmin))
  return((val2 - val1) / (2 * h))
}

ars_init <- function(density_func, domain, n_init = 4) {
  lower <- domain[1]
  upper <- domain[2]

  if (is.infinite(lower) && is.infinite(upper)) {
    x <- seq(-1.5, 1.5, length.out = n_init)
  } else if (is.infinite(lower)) {
    x <- seq(upper - 3, upper - 0.5, length.out = n_init)
  } else if (is.infinite(upper)) {
    x <- seq(lower + 0.5, lower + 3, length.out = n_init)
  } else {
    x <- seq(lower + (upper - lower) * 0.1, lower + (upper - lower) * 0.9, length.out = n_init)
  }

  hx <- sapply(x, function(val) log(max(density_func(val), .Machine$double.xmin)))
  dhx <- sapply(x, function(val) log_density_deriv(density_func, val))

  ord <- order(x)
  x <- x[ord]
  hx <- hx[ord]
  dhx <- dhx[ord]

  # Check log-concavity at initial points: derivative dhx must be non-increasing with x
  for (i in 1:(length(x) - 1)) {
    if (dhx[i] < dhx[i+1] - 1e-4) {
      stop("Non-log-concave density detected: derivative is increasing between initial points.")
    }
  }

  list(x = x, hx = hx, dhx = dhx, lower = lower, upper = upper)
}

update_envelope <- function(state, density_func, new_x) {
  hx_new <- log(max(density_func(new_x), .Machine$double.xmin))
  dhx_new <- log_density_deriv(density_func, new_x)

  x <- c(state$x, new_x)
  hx <- c(state$hx, hx_new)
  dhx <- c(state$dhx, dhx_new)

  ord <- order(x)
  x <- x[ord]
  hx <- hx[ord]
  dhx <- dhx[ord]

  for (i in 1:(length(x) - 1)) {
    if (dhx[i] < dhx[i+1] - 1e-4) {
      stop("Non-log-concave density detected: derivative is increasing between points.")
    }
  }

  list(x = x, hx = hx, dhx = dhx, lower = state$lower, upper = state$upper)
}

sample_upper <- function(state) {
  k <- length(state$x)
  x <- state$x
  hx <- state$hx
  dhx <- state$dhx
  lower <- state$lower
  upper <- state$upper

  z <- numeric(k + 1)
  z[1] <- lower
  z[k + 1] <- upper

  if (k > 1) {
    for (i in 1:(k - 1)) {
      denom <- dhx[i] - dhx[i+1]
      if (abs(denom) < 1e-12) {
        z[i + 1] <- (x[i] + x[i+1]) / 2
      } else {
        z[i + 1] <- (hx[i+1] - hx[i] - x[i+1]*dhx[i+1] + x[i]*dhx[i]) / denom
      }
    }
  }

  for (i in 2:k) {
    if (z[i] <= x[i-1]) z[i] <- x[i-1]
    if (z[i] >= x[i]) z[i] <- x[i]
  }

  int_vals <- numeric(k)
  for (i in 1:k) {
    a <- z[i]
    b <- z[i+1]
    slope <- dhx[i]
    intercept <- hx[i] - slope * x[i]

    if (is.infinite(a) && is.infinite(b)) {
      stop("Domain cannot be entirely infinite without bounds.")
    } else if (is.infinite(a)) {
      if (slope <= 0) {
        int_vals[i] <- exp(intercept + slope * b) / slope
      } else {
        int_vals[i] <- Inf
      }
    } else if (is.infinite(b)) {
      if (slope >= 0) {
        int_vals[i] <- Inf
      } else {
        int_vals[i] <- -exp(intercept + slope * a) / slope
      }
    } else {
      if (abs(slope) < 1e-12) {
        int_vals[i] <- exp(intercept) * (b - a)
      } else {
        int_vals[i] <- (exp(intercept + slope * b) - exp(intercept + slope * a)) / slope
      }
    }
    if (is.nan(int_vals[i]) || int_vals[i] < 0) int_vals[i] <- 0
  }

  tot_int <- sum(int_vals)
  if (tot_int <= 0 || is.infinite(tot_int)) {
    probs <- rep(1/k, k)
  } else {
    probs <- int_vals / tot_int
  }

  chosen_i <- sample(1:k, size = 1, prob = probs)

  a <- z[chosen_i]
  b <- z[chosen_i+1]
  slope <- dhx[chosen_i]
  intercept <- hx[chosen_i] - slope * x[chosen_i]

  u_rand <- runif(1)
  if (is.infinite(a)) {
    prop_x <- b + log(u_rand) / slope
  } else if (is.infinite(b)) {
    prop_x <- a + log(1 - u_rand) / slope
  } else {
    if (abs(slope) < 1e-12) {
      prop_x <- a + u_rand * (b - a)
    } else {
      ea <- exp(slope * a)
      eb <- exp(slope * b)
      prop_x <- log(ea + u_rand * (eb - ea)) / slope
    }
  }

  list(prop_x = prop_x, z = z, chosen_i = chosen_i)
}

ars <- function(density_function, domain, n = 1000) {
  if (!is.function(density_function)) {
    stop("density_function must be a valid R function.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2: c(lower, upper) with lower < upper.")
  }
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n %% 1 != 0) {
    stop("n must be a positive integer representing sample count.")
  }

  state <- ars_init(density_function, domain, n_init = 4)

  samples <- numeric(n)
  accepted <- 0

  while (accepted < n) {
    res <- tryCatch({
      sample_upper(state)
    }, error = function(e) {
      NULL
    })

    if (is.null(res) || is.nan(res$prop_x) || is.infinite(res$prop_x)) {
      next
    }

    prop_x <- res$prop_x

    if (prop_x < domain[1] || prop_x > domain[2]) {
      next
    }

    h_prop <- tryCatch({
      log(max(density_function(prop_x), .Machine$double.xmin))
    }, error = function(e) {
      NA
    })

    if (is.na(h_prop)) next

    x_pts <- state$x
    hx_pts <- state$hx

    l_prop <- -Inf
    if (prop_x >= x_pts[1] && prop_x <= x_pts[length(x_pts)]) {
      idx <- max(which(x_pts <= prop_x))
      if (idx < length(x_pts)) {
        x1 <- x_pts[idx]; x2 <- x_pts[idx+1]
        h1 <- hx_pts[idx]; h2 <- hx_pts[idx+1]
        l_prop <- h1 + (h2 - h1) * (prop_x - x1) / (x2 - x1)
      }
    }

    u_unif <- runif(1)
    chosen_i <- res$chosen_i
    slope <- state$dhx[chosen_i]
    intercept <- state$hx[chosen_i] - slope * state$x[chosen_i]
    u_prop <- intercept + slope * prop_x

    if (log(u_unif) <= l_prop - u_prop) {
      accepted <- accepted + 1
      samples[accepted] <- prop_x
    } else if (log(u_unif) <= h_prop - u_prop) {
      accepted <- accepted + 1
      samples[accepted] <- prop_x
      state <- update_envelope(state, density_function, prop_x)
    } else {
      state <- update_envelope(state, density_function, prop_x)
    }
  }

  return(samples)
}

test <- function() {
  cat("Running Adaptive Rejection Sampler Tests...\n")
  all_passed <- TRUE

  cat("Test 1: Standard Normal Distribution sampling...\n")
  set.seed(42)
  dnorm_unnorm <- function(x) exp(-x^2 / 2)
  norm_samples <- tryCatch({
    ars(dnorm_unnorm, c(-5, 5), n = 2000)
  }, error = function(e) {
    message("Error in normal sampling: ", e$message)
    NULL
  })

  if (!is.null(norm_samples) && length(norm_samples) == 2000) {
    m <- mean(norm_samples)
    s <- sd(norm_samples)
    cat(sprintf("  Mean: %.4f (Expected: 0.0000)\n", m))
    cat(sprintf("  Standard Deviation: %.4f (Expected: 1.0000)\n", s))
    if (abs(m) < 0.1 && abs(s - 1.0) < 0.1) {
      cat("NORMAL_TEST: PASS\n")
      writeLines(as.character(norm_samples), "/app/normal_samples.txt")
    } else {
      cat("NORMAL_TEST: FAIL\n")
      all_passed <- FALSE
    }
  } else {
    cat("NORMAL_TEST: FAIL\n")
    all_passed <- FALSE
  }

  cat("Test 2: Exponential Distribution sampling (rate = 1)...\n")
  set.seed(42)
  dexp_unnorm <- function(x) exp(-x)
  exp_samples <- tryCatch({
    ars(dexp_unnorm, c(0, 10), n = 2000)
  }, error = function(e) {
    message("Error in exponential sampling: ", e$message)
    NULL
  })

  if (!is.null(exp_samples) && length(exp_samples) == 2000) {
    m <- mean(exp_samples)
    s <- sd(exp_samples)
    cat(sprintf("  Mean: %.4f (Expected: 1.0000)\n", m))
    cat(sprintf("  Standard Deviation: %.4f (Expected: 1.0000)\n", s))
    if (abs(m - 1.0) < 0.15 && abs(s - 1.0) < 0.15) {
      cat("EXPONENTIAL_TEST: PASS\n")
      writeLines(as.character(exp_samples), "/app/exponential_samples.txt")
    } else {
      cat("EXPONENTIAL_TEST: FAIL\n")
      all_passed <- FALSE
    }
  } else {
    cat("EXPONENTIAL_TEST: FAIL\n")
    all_passed <- FALSE
  }

  cat("Test 3: Input validation checks...\n")
  passed_validation <- TRUE
  tryCatch({
    ars("not a function", c(-1, 1), 100)
    passed_validation <- FALSE
  }, error = function(e) {})

  tryCatch({
    ars(dnorm_unnorm, c(1, -1), 100)
    passed_validation <- FALSE
  }, error = function(e) {})

  tryCatch({
    ars(dnorm_unnorm, c(-1, 1), -5)
    passed_validation <- FALSE
  }, error = function(e) {})

  if (passed_validation) {
    cat("INPUT_VALIDATION_TEST: PASS\n")
  } else {
    cat("INPUT_VALIDATION_TEST: FAIL\n")
    all_passed <- FALSE
  }

  cat("Test 4: Non-log-concave density check...\n")
  passed_nonlogconcave <- FALSE
  annon_concave <- function(x) exp(x^2)
  tryCatch({
    ars(annon_concave, c(-2, 2), 100)
  }, error = function(e) {
    passed_nonlogconcave <- TRUE
  })

  if (passed_nonlogconcave) {
    cat("NON_LOG_CONCAVE_TEST: PASS\n")
  } else {
    cat("NON_LOG_CONCAVE_TEST: FAIL\n")
    all_passed <- FALSE
  }

  if (all_passed) {
    cat("OVERALL_TEST: PASS\n")
  } else {
    cat("OVERALL_TEST: FAIL\n")
  }
}
EOF

